package com.example.practice;

import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import org.jpos.iso.ISOException;
import org.jpos.iso.ISOUtil;

/** Issues tokens that stand in for card numbers, and turns them back for the station. */
public final class TokenVault {

    /** Encryption and a keyed lookup value for card numbers. The vault never sees the keys. */
    public interface Sealer {
        String seal(String pan);

        String open(String sealed);

        String lookup(String pan);
    }

    record Entry(String requestor, String sealedPan) {
    }

    private final String tokenBin;
    private final Random random;
    private final Sealer sealer;
    private final Map<String, Entry> byToken = new ConcurrentHashMap<>();
    private final Map<String, String> byRequestorAndCard = new ConcurrentHashMap<>();

    /** tokenBin: the range the network reserved for this vault's tokens, 6 to 8 digits. */
    public TokenVault(String tokenBin, Random random, Sealer sealer) {
        this.tokenBin = tokenBin;
        this.random = random;
        this.sealer = sealer;
    }

    /** The requestor's token for this card: the one it already has, or a new one. */
    public String tokenize(String requestor, String pan) {
        return byRequestorAndCard.computeIfAbsent(key(requestor, pan),
            k -> issue(new Entry(requestor, sealer.seal(pan))));
    }

    /** The card number behind a token, for the station building a request on the requestor's behalf. */
    public String detokenize(Set<String> callerPermissions, String requestor, String token) throws ISOException {
        if (!callerPermissions.contains("DETOKENIZE")) {
            throw new SecurityException("caller may not detokenize");
        }
        Entry e = byToken.get(token);
        if (e == null || !e.requestor().equals(requestor)) {
            throw new ISOException("unknown token");
        }
        return sealer.open(e.sealedPan());
    }

    /** Withdraws a token, for example when the customer removes a saved card. */
    public void revoke(String token) {
        if (byToken.remove(token) != null) {
            byRequestorAndCard.values().remove(token);
        }
    }

    /** What the vault files a requestor's token for this card under. */
    String key(String requestor, String pan) {
        return requestor + ":" + sealer.lookup(pan);
    }

    /** A token nobody holds yet, recorded for this entry. */
    String issue(Entry entry) {
        String token = newToken();
        while (byToken.putIfAbsent(token, entry) != null) {
            token = newToken();
        }
        return token;
    }

    /** A candidate token: 16 digits, each drawn with random.nextInt(10) after the range. */
    String newToken() {
        StringBuilder sb = new StringBuilder(tokenBin);
        while (sb.length() < 15) {
            sb.append(random.nextInt(10));
        }
        return sb.append(ISOUtil.calcLUHN(sb.toString())).toString();
    }
}

import com.example.practice.TokenVault;
import java.util.Random;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.jpos.iso.ISOException;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            TokenVault vault = new TokenVault("9123450", new Random(77), new TokenVault.Sealer() {
                public String seal(String pan) { return "sealed:" + new StringBuilder(pan).reverse(); }
                public String open(String sealed) { return new StringBuilder(sealed.substring(7)).reverse().toString(); }
                public String lookup(String pan) { return "lookup:" + Integer.toHexString(("k7" + pan).hashCode()); }
            });
            Set<String> station = Set.of("DETOKENIZE");
            String gym = vault.tokenize("gym-2", "4012888888881881");
            System.out.println("station for gym-2: " + ask(vault, station, "gym-2", gym));
            System.out.println("gym app's own credentials: " + ask(vault, Set.of("TOKENIZE"), "gym-2", gym));
            System.out.println("station for florist-5: " + ask(vault, station, "florist-5", gym));
            System.out.println("made-up token: " + ask(vault, station, "gym-2", "9123450000000004"));
            vault.revoke(gym);
            System.out.println("after revoke: " + ask(vault, station, "gym-2", gym));
            System.out.println("new token for the same card: " + !gym.equals(vault.tokenize("gym-2", "4012888888881881")));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static String ask(TokenVault vault, Set<String> permissions, String requestor, String token) {
        try {
            return vault.detokenize(permissions, requestor, token);
        } catch (SecurityException | ISOException refused) {
            return "refused (" + refused.getClass().getSimpleName() + ": " + refused.getMessage() + ")";
        }
    }
}

